//! Generates the realm-local classic bootstrap used by the browser host.
//!
//! Run with `cargo run -p nsh-bundler --example browser_bootstrap` after
//! changing its JavaScript sources; pass `-- --check` to verify freshness.

use std::{env, fs, path::PathBuf};

use anyhow::{Context, Result, bail, ensure};
use rolldown::{Bundler, BundlerOptions, InputItem, OutputFormat};
use rolldown_common::{CodeSplittingMode, Output, Platform, RawMinifyOptions, StrictMode};

fn main() -> Result<()> {
    let args: Vec<_> = env::args().skip(1).collect();
    ensure!(
        args.is_empty() || args == ["--check"],
        "expected only --check"
    );
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let target = root.join("../nsh-platform-web/web/browser/bootstrap.js");
    let code = tokio::runtime::Builder::new_current_thread()
        .build()?
        .block_on(generate(root))?;
    if args.is_empty() {
        fs::write(&target, code).with_context(|| format!("write {}", target.display()))?;
    } else {
        let actual = fs::read_to_string(&target)?;
        ensure!(
            actual == code,
            "browser bootstrap is stale; run cargo run -p nsh-bundler --example browser_bootstrap"
        );
    }
    Ok(())
}

async fn generate(root: PathBuf) -> Result<String> {
    let mut bundler = Bundler::new(BundlerOptions {
        input: Some(vec![InputItem {
            import: "./examples/browser-bootstrap.js".into(),
            ..Default::default()
        }]),
        cwd: Some(root),
        dir: Some(".".into()),
        format: Some(OutputFormat::Iife),
        strict: Some(StrictMode::Always),
        platform: Some(Platform::Browser),
        minify: Some(RawMinifyOptions::Bool(false)),
        code_splitting: Some(CodeSplittingMode::Bool(false)),
        ..Default::default()
    })
    .map_err(|e| anyhow::anyhow!("browser bootstrap: {e:?}"))?;
    let output = bundler
        .generate()
        .await
        .map_err(|e| anyhow::anyhow!("browser bootstrap: {e:?}"))?;
    ensure!(output.assets.len() == 1, "expected one bootstrap script");
    let Some(Output::Chunk(chunk)) = output.assets.into_iter().next() else {
        bail!("expected a JavaScript bootstrap chunk");
    };
    ensure!(
        chunk.imports.is_empty() && chunk.dynamic_imports.is_empty(),
        "the classic bootstrap must not load other modules"
    );
    Ok(format!(
        "// Generated by cargo run -p nsh-bundler --example browser_bootstrap; do not edit.\n{}",
        chunk.code
    ))
}
